import sys

MINOR = {"a", "an", "and", "as", "at", "but", "by", "for", "in", "nor", "of", "on", "or", "the", "to"}


def headline(line):
    out = []
    line = line.strip()
    if not line:
        return ""
    for word in line.split():
        stripped_word = word.strip('.,!?;')
        if stripped_word.lower() in MINOR:
            if out and out[-1] != "":  # not the first word
                out.append(stripped_word.lower())
            else:  # first or only word
                out.append(stripped_word.lower())
        else:
            first_char = stripped_word[0].upper()
            rest = stripped_word[1:].lower()
            out.append(first_char + rest)
    return " ".join(out)


def main():
    for line in sys.stdin:
        print(headline(line))


if __name__ == "__main__":
    main()
